package net.civeira.phylax.features.document.templatesnippet.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.document.templatesnippet.domain.TemplateSnippet;
import net.civeira.phylax.features.document.templatesnippet.domain.event.TemplateSnippetEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class TemplateSnippetEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<TemplateSnippetEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final TemplateSnippet entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
